import { spawn } from 'node:child_process';
import { createInterface } from 'node:readline';
import fs from 'node:fs';

const child = spawn('bun', ['src/cli/serve-stdio.ts'], { env: { ...process.env, TOOLBOX_GATEWAY_URL: 'http://127.0.0.1:1', TOOLBOX_HOST: '' }, stdio: ['pipe', 'pipe', 'pipe'] });
let stderr = '';
child.stderr.on('data', b => { stderr += String(b); });
const lines = createInterface({ input: child.stdout });
const messages: any[] = [];
const waiters: Array<(value: any) => void> = [];
lines.on('line', line => { const msg = JSON.parse(line); messages.push(msg); waiters.shift()?.(msg); });
const next = () => new Promise<any>(resolve => waiters.push(resolve));
const send = (msg: unknown) => child.stdin.write(JSON.stringify(msg) + '\n');
const timeout = setTimeout(() => { child.kill(); throw new Error(`stdio timeout: ${stderr}`); }, 3000);
let pending = next();
send({ jsonrpc: '2.0', id: 'initialize', method: 'initialize', params: { protocolVersion: '2025-06-18', clientInfo: { name: 'Offline Host' } } });
await pending;
pending = next();
send({ jsonrpc: '2.0', method: 'notifications/initialized' });
send({ jsonrpc: '2.0', id: 0, method: 'ping' });
await pending;
pending = next();
child.stdin.write('{broken\n');
await pending;
const exit = new Promise<number | null>(resolve => child.on('exit', resolve));
child.stdin.end();
const exitCode = await exit;
clearTimeout(timeout);
fs.writeFileSync(process.argv[2], JSON.stringify({ messages, exitCode }));
